#include "../Core/BIPCore.hpp"
#include <fstream>
#include <iostream>
#include <codecvt>
#include <locale>
using namespace bip;
static Bytes load(const std::string& p){std::ifstream f(p,std::ios::binary);if(!f)throw Error("file not found: "+p);return Bytes(std::istreambuf_iterator<char>(f),{});}
static void save(const std::string& p,const Bytes& b){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(b.data()),b.size());if(!f)throw Error("write failed");}
static std::u16string text(const Bytes& b){std::wstring_convert<std::codecvt_utf8_utf16<char16_t>,char16_t> c;return c.from_bytes(std::string(b.begin(),b.end()));}
int main(int argc,char** argv){try{if(argc<4)throw Error("operation input output key [args]");std::string op=argv[1],input=argv[2],out=argv[3],key=argc>4?argv[4]:std::string(128,'1');if(op=="shake"){save(out,shake(load(input),400));return 0;}if(op=="sealtext"){save(out,sealText(text(load(input)),key,1793701842,Bytes(48,7)));return 0;}if(op=="opentext"){auto r=openText(load(input),key);std::wstring_convert<std::codecvt_utf8_utf16<char16_t>,char16_t> c;auto s=c.to_bytes(r.text);save(out,Bytes(s.begin(),s.end()));std::cout<<r.seconds;return 0;}if(op=="sealimage"){need_args: if(argc<9)throw Error("width height png quality");Prepared p{load(input),std::stoi(argv[5]),std::stoi(argv[6]),std::stoi(argv[8]),std::string(argv[7])=="1"};save(out,sealImage(p,key,1793701842,Bytes(48,9)));return 0;}if(op=="openimage"){auto r=openImage(load(input),key);save(out,r.image.data);std::cout<<r.seconds;return 0;}if(op=="rs"){auto data=load(input),coded=rsEncode(data);for(size_t i=0;i<coded.size();i+=255)for(size_t j=0;j<16&&i+j<coded.size();j++)coded[i+j]^=uint8_t(j+1);int corrected=0;auto decoded=rsDecode(coded,corrected);if(decoded!=data)throw Error("RS mismatch");save(out,decoded);std::cout<<corrected;return 0;}if(argc<7)throw Error("width height required");int w=std::stoi(argv[5]),h=std::stoi(argv[6]);Image im(w,h,load(input));if(op=="encode"){if(argc<10)throw Error("env strong dense required");auto env=load(argv[7]);encode(im,env,key,std::string(argv[8])=="1",std::string(argv[9])=="1");save(out,im.rgb);}else if(op=="decode"){auto r=decode(im,key);if(r.image.data.empty()){std::wstring_convert<std::codecvt_utf8_utf16<char16_t>,char16_t> c;auto s=c.to_bytes(r.text);save(out,Bytes(s.begin(),s.end()));}else save(out,r.image.data);std::cout<<r.seconds<<" "<<r.recovered<<"/"<<r.total<<" "<<r.rotation;}else throw Error("unknown operation");return 0;}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
